entries[345218] = { ["name"] = "Hungernde Leere", ["text"] = "'Leerenblitz' macht das Ziel verwundbar gegenüber der Leere, wodurch ihr ihm 12 Sek. lang 10% mehr Schaden zufügt. Dieser Effekt kann immer nur auf einem Ziel gleichzeitig aktiv sein.\n\nWenn Ihr 'Leerenblitz' gegen einen bereits verwundbaren Gegner einsetzt, wird Eure Leerengestalt um 2 Sek. verlängert. Wenn 'Leerenblitz' dabei kritisch trifft, wird die Leerengestalt stattdessen um 4 Sek. verlängert." }
entries[345219] = { ["name"] = "Hungernde Leere", ["text"] = "100 Meter Reichweite\nSofort\n'Leerenblitz' macht das Ziel verwundbar gegenüber der Leere, wodurch ihr ihm 12 Sek. lang 10% mehr Schaden zufügt. Dieser Effekt kann immer nur auf einem Ziel gleichzeitig aktiv sein.\n\nWenn Ihr 'Leerenblitz' gegen einen bereits verwundbaren Gegner einsetzt, wird Eure Leerengestalt um 2 Sek. verlängert. Wenn 'Leerenblitz' dabei kritisch trifft, wird die Leerengestalt stattdessen um 4 Sek. verlängert." }
